#include "render_settings.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>

namespace darkangel::editor_app::render {
namespace {
float number(const nlohmann::json& value, const char* key, float fallback, float low, float high) {
    const float n = key[0] ? value.value(key, fallback) : value.get<float>();
    if (!std::isfinite(n) || n < low || n > high) throw std::runtime_error(std::string("Rendering field out of range: ") + key);
    return n;
}
rendering::Color3 color(const nlohmann::json& value, const char* key, rendering::Color3 fallback, float high = 16) {
    const auto array = value.value(key, nlohmann::json::array({fallback.r, fallback.g, fallback.b}));
    if (!array.is_array() || array.size() != 3) throw std::runtime_error(std::string("Rendering colour field: ") + key);
    return {number(array[0], "", fallback.r, 0, high), number(array[1], "", fallback.g, 0, high), number(array[2], "", fallback.b, 0, high)};
}
void schema(const nlohmann::json& value, const char* kind) { if (value.value("schema", 1) != 1) throw std::runtime_error(std::string("Unsupported ") + kind + " schema"); }
}
const char* light_type_name(rendering::LightType type) { return type == rendering::LightType::Directional ? "Directional Light" : type == rendering::LightType::Spot ? "Spot Light" : "Point Light"; }
AuthoredLight decode_light(const nlohmann::json& value) {
    if (!value.is_object()) throw std::runtime_error("Light component must be an object"); schema(value, "light component"); AuthoredLight result;
    const auto type = value.value("type", std::string("point")); if (type == "directional") result.type = rendering::LightType::Directional; else if (type == "spot") result.type = rendering::LightType::Spot; else if (type != "point") throw std::runtime_error("Light type must be directional, point or spot");
    result.enabled = value.value("enabled", true); result.cast_shadows = value.value("cast_shadows", false); result.color = color(value, "color", result.color, 1); result.intensity = number(value, "intensity", result.type == rendering::LightType::Directional ? 1.2f : 2, 0, 100); result.range = number(value, "range", 8, .01f, 1000); result.inner_cone_degrees = number(value, "inner_cone", 20, 0, 89); result.outer_cone_degrees = number(value, "outer_cone", 35, .01f, 179); if (result.inner_cone_degrees > result.outer_cone_degrees) throw std::runtime_error("Spot inner cone exceeds outer cone"); result.falloff = number(value, "falloff", 2, .1f, 8); return result;
}
nlohmann::json encode_light(const AuthoredLight& value) { return {{"schema", 1}, {"type", value.type == rendering::LightType::Directional ? "directional" : value.type == rendering::LightType::Spot ? "spot" : "point"}, {"enabled", value.enabled}, {"cast_shadows", value.cast_shadows}, {"color", {value.color.r, value.color.g, value.color.b}}, {"intensity", value.intensity}, {"range", value.range}, {"inner_cone", value.inner_cone_degrees}, {"outer_cone", value.outer_cone_degrees}, {"falloff", value.falloff}}; }
SceneRenderingSettings decode_rendering_settings(const nlohmann::json& value) {
    if (!value.is_object()) throw std::runtime_error("Rendering settings must be an object"); schema(value, "rendering settings"); SceneRenderingSettings result;
    if (value.contains("main_light") && !value.at("main_light").is_null()) result.main_light = StableId::parse(value.at("main_light").get<std::string>()); result.gpu_clustered = value.value("gpu_clustered", true); if (value.contains("clusters")) { const auto& clusters = value.at("clusters"); result.clusters.tile_size = std::clamp(clusters.value("tile_size", 16u), 4u, 64u); result.clusters.depth_slices = std::clamp(clusters.value("depth_slices", 24u), 1u, 128u); result.clusters.max_candidates = std::clamp(clusters.value("max_candidates", 64u), 1u, 64u); result.clusters.shading_budget = std::clamp(clusters.value("shading_budget", 4u), 1u, 4u); } result.sky_enabled = value.value("sky_enabled", true); result.sky_color = color(value, "sky_color", result.sky_color, 16);
    if (value.contains("shadows")) { const auto& shadows = value.at("shadows"); result.shadows.cascades_enabled = shadows.value("enabled", true); result.shadows.cascade_count = shadows.value("cascade_count", 4u); result.shadows.resolution = shadows.value("resolution", 2048u); if (result.shadows.cascade_count < 1 || result.shadows.cascade_count > 4) throw std::runtime_error("Shadow cascade count must be one to four"); if (result.shadows.resolution < 512 || result.shadows.resolution > 4096 || (result.shadows.resolution & (result.shadows.resolution - 1)) != 0) throw std::runtime_error("Shadow resolution must be a power of two from 512 to 4096"); result.shadows.distance = number(shadows, "distance", result.shadows.distance, .1f, 100000); result.shadows.depth_bias = number(shadows, "depth_bias", result.shadows.depth_bias, 0, 1); result.shadows.normal_bias = number(shadows, "normal_bias", result.shadows.normal_bias, 0, 1); result.shadows.split_distribution = number(shadows, "split_distribution", result.shadows.split_distribution, 0, 1); }
    if (value.contains("sky")) { const auto& sky = value.at("sky"); result.sky.procedural = sky.value("procedural", false); if (sky.contains("hdr_texture") && !sky.at("hdr_texture").is_null()) result.sky.hdr_texture = AssetId::parse(sky.at("hdr_texture").get<std::string>()); result.sky.hdr_intensity = number(sky, "hdr_intensity", result.sky.hdr_intensity, 0, 100); result.sky.hdr_rotation_degrees = number(sky, "hdr_rotation_degrees", result.sky.hdr_rotation_degrees, -3600, 3600); result.sky.zenith = color(sky, "zenith", result.sky.zenith, 16); result.sky.horizon = color(sky, "horizon", result.sky.horizon, 16); result.sky.ground = color(sky, "ground", result.sky.ground, 16); result.sky.sun_color = color(sky, "sun_color", result.sky.sun_color, 16); if (sky.contains("sun_direction")) { const auto& direction = sky.at("sun_direction"); if (!direction.is_array() || direction.size() != 3) throw std::runtime_error("Sky sun direction must have three values"); for (unsigned i = 0; i < 3; ++i) result.sky.sun_direction[i] = number(direction[i], "", result.sky.sun_direction[i], -1, 1); } result.sky.sun_size = number(sky, "sun_size", result.sky.sun_size, .001f, .5f); result.sky.sun_intensity = number(sky, "sun_intensity", result.sky.sun_intensity, 0, 100); result.sky.cloud_amount = number(sky, "cloud_amount", result.sky.cloud_amount, 0, 1); result.sky.seed = sky.value("seed", 0u); }
    if (value.contains("toon")) { const auto& toon = value.at("toon"); result.toon.ambient_color = color(toon, "ambient_color", result.toon.ambient_color, 16); result.toon.ambient_strength = number(toon, "ambient_strength", result.toon.ambient_strength, 0, 16); result.toon.shadow_tint = color(toon, "shadow_tint", result.toon.shadow_tint, 1); if (toon.contains("thresholds")) { const auto& thresholds = toon.at("thresholds"); if (!thresholds.is_array() || thresholds.size() != 3) throw std::runtime_error("Toon thresholds must have three values"); for (unsigned i = 0; i < 3; ++i) result.toon.band_thresholds[i] = number(thresholds[i], "", result.toon.band_thresholds[i], 0, 1); if (result.toon.band_thresholds[0] > result.toon.band_thresholds[1] || result.toon.band_thresholds[1] > result.toon.band_thresholds[2]) throw std::runtime_error("Toon thresholds must be ordered"); } result.toon.transition_softness = number(toon, "softness", result.toon.transition_softness, 0, 1); result.toon.local_light_strength = number(toon, "local_strength", result.toon.local_light_strength, 0, 16); }
    if (value.contains("fog")) { const auto& fog = value.at("fog"); result.fog.enabled = fog.value("enabled", false); const auto mode = fog.value("mode", std::string("linear")); if (mode != "linear" && mode != "exponential") throw std::runtime_error("Fog mode must be linear or exponential"); result.fog.exponential = mode == "exponential"; result.fog.color = color(fog, "color", result.fog.color, 16); result.fog.start = number(fog, "start", result.fog.start, 0, 100000); result.fog.end = number(fog, "end", result.fog.end, .01f, 100000); if (result.fog.end < result.fog.start) throw std::runtime_error("Fog end precedes start"); result.fog.density = number(fog, "density", result.fog.density, 0, 10); result.fog.height = number(fog, "height", result.fog.height, -10000, 10000); result.fog.height_falloff = number(fog, "height_falloff", result.fog.height_falloff, 0, 10); }
    if (value.contains("post")) { const auto& post = value.at("post"); result.post.bloom = post.value("bloom", false); result.post.bloom_threshold = number(post, "bloom_threshold", result.post.bloom_threshold, 0, 100); result.post.bloom_intensity = number(post, "bloom_intensity", result.post.bloom_intensity, 0, 100); result.post.exposure = number(post, "exposure", result.post.exposure, -16, 16); result.post.exposure_compensation = number(post, "exposure_compensation", result.post.exposure_compensation, -16, 16); result.post.contrast = number(post, "contrast", result.post.contrast, 0, 4); result.post.saturation = number(post, "saturation", result.post.saturation, 0, 4); result.post.fxaa = post.value("fxaa", true); if (post.contains("outline")) { const auto& outline = post.at("outline"); result.post.outline.enabled = outline.value("enabled", true); result.post.outline.color = color(outline, "color", result.post.outline.color, 1); result.post.outline.thickness = number(outline, "thickness", result.post.outline.thickness, .25f, 4); result.post.outline.depth_sensitivity = number(outline, "depth_sensitivity", result.post.outline.depth_sensitivity, 0, 1000); result.post.outline.normal_sensitivity = number(outline, "normal_sensitivity", result.post.outline.normal_sensitivity, 0, 16); result.post.outline.group_sensitivity = number(outline, "group_sensitivity", result.post.outline.group_sensitivity, 0, 16); result.post.outline.fade_start = number(outline, "fade_start", result.post.outline.fade_start, 0, 100000); result.post.outline.fade_end = number(outline, "fade_end", result.post.outline.fade_end, .01f, 100000); if (result.post.outline.fade_end < result.post.outline.fade_start) throw std::runtime_error("Outline fade end precedes start"); } }
    return result;
}
nlohmann::json encode_rendering_settings(const SceneRenderingSettings& value) { return {{"schema", 1}, {"main_light", value.main_light ? nlohmann::json(value.main_light.text()) : nlohmann::json(nullptr)}, {"gpu_clustered", value.gpu_clustered}, {"clusters", {{"tile_size", value.clusters.tile_size}, {"depth_slices", value.clusters.depth_slices}, {"max_candidates", value.clusters.max_candidates}, {"shading_budget", value.clusters.shading_budget}}}, {"sky_enabled", value.sky_enabled}, {"sky_color", {value.sky_color.r, value.sky_color.g, value.sky_color.b}}, {"sky", {{"procedural", value.sky.procedural}, {"hdr_texture", value.sky.hdr_texture != AssetId{} ? nlohmann::json(value.sky.hdr_texture.text()) : nlohmann::json(nullptr)}, {"hdr_intensity", value.sky.hdr_intensity}, {"hdr_rotation_degrees", value.sky.hdr_rotation_degrees}, {"zenith", {value.sky.zenith.r, value.sky.zenith.g, value.sky.zenith.b}}, {"horizon", {value.sky.horizon.r, value.sky.horizon.g, value.sky.horizon.b}}, {"ground", {value.sky.ground.r, value.sky.ground.g, value.sky.ground.b}}, {"sun_direction", value.sky.sun_direction}, {"sun_color", {value.sky.sun_color.r, value.sky.sun_color.g, value.sky.sun_color.b}}, {"sun_size", value.sky.sun_size}, {"sun_intensity", value.sky.sun_intensity}, {"cloud_amount", value.sky.cloud_amount}, {"seed", value.sky.seed}}}, {"shadows", {{"enabled", value.shadows.cascades_enabled}, {"cascade_count", value.shadows.cascade_count}, {"resolution", value.shadows.resolution}, {"distance", value.shadows.distance}, {"depth_bias", value.shadows.depth_bias}, {"normal_bias", value.shadows.normal_bias}, {"split_distribution", value.shadows.split_distribution}}}, {"toon", {{"ambient_color", {value.toon.ambient_color.r, value.toon.ambient_color.g, value.toon.ambient_color.b}}, {"ambient_strength", value.toon.ambient_strength}, {"shadow_tint", {value.toon.shadow_tint.r, value.toon.shadow_tint.g, value.toon.shadow_tint.b}}, {"thresholds", value.toon.band_thresholds}, {"softness", value.toon.transition_softness}, {"local_strength", value.toon.local_light_strength}}}, {"fog", {{"enabled", value.fog.enabled}, {"mode", value.fog.exponential ? "exponential" : "linear"}, {"color", {value.fog.color.r, value.fog.color.g, value.fog.color.b}}, {"start", value.fog.start}, {"end", value.fog.end}, {"density", value.fog.density}, {"height", value.fog.height}, {"height_falloff", value.fog.height_falloff}}}, {"post", {{"bloom", value.post.bloom}, {"bloom_threshold", value.post.bloom_threshold}, {"bloom_intensity", value.post.bloom_intensity}, {"exposure", value.post.exposure}, {"exposure_compensation", value.post.exposure_compensation}, {"contrast", value.post.contrast}, {"saturation", value.post.saturation}, {"fxaa", value.post.fxaa}, {"outline", {{"enabled", value.post.outline.enabled}, {"color", {value.post.outline.color.r, value.post.outline.color.g, value.post.outline.color.b}}, {"thickness", value.post.outline.thickness}, {"depth_sensitivity", value.post.outline.depth_sensitivity}, {"normal_sensitivity", value.post.outline.normal_sensitivity}, {"group_sensitivity", value.post.outline.group_sensitivity}, {"fade_start", value.post.outline.fade_start}, {"fade_end", value.post.outline.fade_end}}}}}}; }
}
